"use client";
import { useId } from "react";
import { useWorkspaceRoleUsage } from "@/components/workspace-quota";
import { PRESET_ROLES, savedRoleTitles, normalizeRole } from "@/lib/roles";

export function useRoleSuggestions(roles?: readonly string[]) {
  const usage = useWorkspaceRoleUsage();
  const id = useId();
  const seen = new Set<string>();
  const titles = (roles ?? [...PRESET_ROLES, ...savedRoleTitles(usage)]).filter(
    (title) => {
      const key = normalizeRole(title);
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    },
  );
  return {
    list: id,
    suggestions: (
      <datalist id={id}>
        {titles.map((title) => (
          <option key={title} value={title} />
        ))}
      </datalist>
    ),
  };
}
